async (page)=>{await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:5173/fiche-creation.html');await page.emulateMedia({reducedMotion:'reduce'});await page.screenshot({path:'prototype/preview/fiche-desktop.png'});await page.locator('.section-nav a[href="#parcours"]').click();await page.waitForTimeout(150);if(await page.locator('.section-nav a[aria-current]').getAttribute('href')!=='#parcours')throw Error('Repère de lecture');await page.screenshot({path:'prototype/preview/fiche-parcours.png'});await page.context().grantPermissions(['clipboard-read','clipboard-write']);await page.locator('#share').click();if(!(await page.evaluate(()=>navigator.clipboard.readText())).endsWith('/fiche-creation.html?id=cite-ciel-mer'))throw Error('Partage');await page.locator('#report-open').click();await page.locator('#report-note').fill('La configuration mérite une nouvelle vérification.');await page.locator('#report-form button').click();if(await page.locator('#report-dialog').evaluate(d=>d.open))throw Error('Signalement');for(const width of [1440,1024,768,375,320]){await page.setViewportSize({width,height:900});if(!await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth))throw Error('Débordement '+width);}await page.setViewportSize({width:1440,height:1000});for(let y=0;y<await page.evaluate(()=>document.body.scrollHeight);y+=600){await page.evaluate(y=>scrollTo(0,y),y);await page.waitForTimeout(60);}await page.evaluate(()=>scrollTo(0,0));await page.waitForTimeout(100);await page.screenshot({path:'prototype/preview/fiche-full.png',fullPage:true});return 'Repère de lecture, partage, signalement et responsive validés';}
